#!/usr/bin/env bash
set -euo pipefail

OPEN_AIRPORTS_FILE=$1
RUNWAYS_FILE=$2
OUTPUT_FILE=$3

TMP_OUTPUT_FILE="${OUTPUT_FILE}.tmp"

awk -F $'\t' '
  BEGIN { OFS = FS }
  FNR == NR {
    if (FNR == 1) {
      next
    }
    if ($5 != "1") {
      count[$1] += 1
      if ($2 != "" && (!($1 in max) || ($2 + 0) > max[$1])) {
        max[$1] = $2 + 0
      }
    }
    next
  }
  FNR == 1 {
    print $0, "runway_count", "longest_runway_ft"
    next
  }
  {
    airport = $1
    runway_count = (airport in count) ? count[airport] : 0
    longest = (airport in max) ? max[airport] : ""
    print $0, runway_count, longest
  }
' "$RUNWAYS_FILE" "$OPEN_AIRPORTS_FILE" > "$TMP_OUTPUT_FILE"

mv "$TMP_OUTPUT_FILE" "$OUTPUT_FILE"

